CREATE TABLE user_strategies (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, name VARCHAR(255) NOT NULL, description TEXT, strategy_data JSONB NOT NULL, public BOOLEAN DEFAULT true, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW());
CREATE POLICY "Users can insert their own strategies" ON user_strategies FOR INSERT WITH CHECK (auth.uid() = user_id); CREATE POLICY "Anyone can view public strategies" ON user_strategies FOR SELECT USING (public = true); CREATE POLICY "Users can update their own strategies" ON user_strategies FOR UPDATE USING (auth.uid() = user_id); CREATE POLICY "Users can delete their own strategies" ON user_strategies FOR DELETE USING (auth.uid() = user_id);
